<?php
namespace App\Http\Controllers\Admin; use App\Domain\WorkProcesses\{WorkProcessDependencyInspector,WorkProcessManager,WorkProcessRegistry,WorkProcessRelationManager,WorkProcessViewData}; use App\Domain\Installation\WebsiteSettings; use App\Http\Controllers\{Controller,PublicSiteController}; use App\Http\Requests\WorkProcesses\SaveWorkProcessRequest; use App\Models\{WorkProcess,Industry,Page,Product,Solution}; use Illuminate\Contracts\View\View; use Illuminate\Http\{RedirectResponse,Request,Response}; use Illuminate\Support\Carbon; use Illuminate\Support\Str; use Illuminate\Validation\Rule; class WorkProcessController extends Controller { public function index(Request $request):View{$f=$request->validate(['search'=>['nullable','string','max:160'],'status'=>['nullable',Rule::in(['draft','published','scheduled','archived'])],'featured'=>['nullable','in:0,1'],'archived'=>['nullable','in:with,only,without'],'template'=>['nullable',Rule::in(WorkProcessRegistry::TEMPLATES)],'sort'=>['nullable','in:title,updated_at,published_at,display_order'],'direction'=>['nullable','in:asc,desc']]);$q=WorkProcess::withCount(['stages','relatedSolutions','relatedProducts','relatedIndustries','relatedPages'])->when($f['search']??null,fn($q,$v)=>$q->where(fn($q)=>$q->where('title','like',"%$v%")->orWhere('slug','like',"%$v%")))->when($f['status']??null,fn($q,$v)=>$q->where('status',$v))->when($f['template']??null,fn($q,$v)=>$q->where('template',$v))->when(isset($f['featured']),fn($q)=>$q->where('is_featured',(bool)$f['featured']));if(($f['archived']??'without')==='only')$q->whereNotNull('archived_at');elseif(($f['archived']??'without')==='without')$q->whereNull('archived_at');return view('admin.work-processes.index',['processes'=>$q->orderBy($f['sort']??'display_order',$f['direction']??'asc')->paginate(20)->withQueryString(),'f'=>$f,'templates'=>WorkProcessRegistry::TEMPLATES]);} public function create():View{return $this->editor(new WorkProcess);} public function store(SaveWorkProcessRequest $request,WorkProcessManager $manager):RedirectResponse{$item=$manager->save($request->validated(),null,$request->user()->id);return redirect()->route('admin.work-processes.edit',$item)->with('status','Draft work process created.');} public function edit(WorkProcess $workProcess):View{return $this->editor($workProcess);} public function update(SaveWorkProcessRequest $request,WorkProcess $workProcess,WorkProcessManager $manager):RedirectResponse{$manager->save($request->validated(),$workProcess,$request->user()->id);return back()->with('status','Work process saved.');} private function editor(WorkProcess $item):View{if($item->exists)$item->load(['stages.deliverables','relatedSolutions','relatedProducts','relatedIndustries','relatedPages']);return view('admin.work-processes.editor',['process'=>$item,'templates'=>WorkProcessRegistry::TEMPLATES,'heroes'=>WorkProcessRegistry::HERO_STYLES,'icons'=>WorkProcessRegistry::ICONS,'solutions'=>Solution::whereNull('archived_at')->orderBy('title')->limit(200)->get(),'products'=>Product::whereNull('archived_at')->orderBy('title')->limit(200)->get(),'industries'=>Industry::whereNull('archived_at')->orderBy('title')->limit(200)->get(),'pages'=>Page::whereNull('archived_at')->orderBy('title')->limit(200)->get(),'dependencies'=>$item->exists?app(WorkProcessDependencyInspector::class)->inspect($item):null]);} public function publish(WorkProcess $workProcess,WorkProcessManager $manager):RedirectResponse{$manager->publish($workProcess);return back()->with('status','Work process published.');} public function schedule(Request $request,WorkProcess $workProcess,WorkProcessManager $manager):RedirectResponse{$value=$request->validate(['scheduled_for'=>['required','date']]);$timezone=app(WebsiteSettings::class)->current()?->timezone?:'UTC';$manager->schedule($workProcess,Carbon::parse($value['scheduled_for'],$timezone)->utc()->toDateTimeString());return back()->with('status','Work process scheduled.');} public function unpublish(WorkProcess $workProcess,WorkProcessManager $manager):RedirectResponse{$manager->unpublish($workProcess);return back();} public function archive(WorkProcess $workProcess,WorkProcessManager $manager):RedirectResponse{$manager->archive($workProcess);return back();} public function restore(WorkProcess $workProcess,WorkProcessManager $manager):RedirectResponse{$manager->restore($workProcess);return back();} public function duplicate(Request $request,WorkProcess $workProcess,WorkProcessManager $manager):RedirectResponse{return redirect()->route('admin.work-processes.edit',$manager->duplicate($workProcess,$request->user()->id));} public function move(WorkProcess $workProcess,string $direction,WorkProcessManager $manager):RedirectResponse{$manager->move($workProcess,$direction);return back();} public function relations(Request $request,WorkProcess $workProcess,WorkProcessRelationManager $manager):RedirectResponse{$d=$request->validate(['related_solution_ids'=>['array','max:8'],'related_solution_ids.*'=>['integer','distinct','exists:solutions,id'],'related_product_ids'=>['array','max:8'],'related_product_ids.*'=>['integer','distinct','exists:products,id'],'related_industry_ids'=>['array','max:8'],'related_industry_ids.*'=>['integer','distinct','exists:industries,id'],'related_page_ids'=>['array','max:6'],'related_page_ids.*'=>['integer','distinct','exists:pages,id']]);$manager->sync($workProcess,$d['related_solution_ids']??[],$d['related_product_ids']??[],$d['related_industry_ids']??[],$d['related_page_ids']??[]);return back();} public function preview(Request $request,WorkProcess $workProcess,WorkProcessViewData $data):Response{return response()->view('work-processes.show',['process'=>$data->preview($workProcess),'preview'=>true]+app(PublicSiteController::class)->sharedViewData($request))->header('Cache-Control','no-store, private, max-age=0')->header('X-Robots-Tag','noindex, nofollow');} }
